mapper.select:
select u.id, u.username, u.nickname, u.pic, u.signature
from t_register_users u
where u.username != #{self,jdbcType=VARCHAR}
  and u.status = '1'
  and u.username not in (
      select c.username from t_chat_users c
      where c.owner_user = #{self,jdbcType=VARCHAR}
  )
  and (
      u.username like concat(#{keyword,jdbcType=VARCHAR}, '%')
      or ifnull(u.nickname, '') like concat(#{keyword,jdbcType=VARCHAR}, '%')
  )
order by char_length(u.username), u.username
limit #{limit,jdbcType=INTEGER}

select id, owner_user, username, label_name, group_id, crt_time
from t_chat_users
where owner_user = #{ownerUser,jdbcType=VARCHAR}
  and username = #{username,jdbcType=VARCHAR}
limit 1

mapper.delete:
delete from t_chat_users
where owner_user = #{ownerUser,jdbcType=VARCHAR}
  and username = #{username,jdbcType=VARCHAR}

mapper.update:
update t_chat_users
set label_name = #{labelName,jdbcType=VARCHAR}
where owner_user = #{ownerUser,jdbcType=VARCHAR}
  and username = #{username,jdbcType=VARCHAR}

mapper.select:
select count(*)
from t_chat_users
where owner_user = #{ownerUser,jdbcType=VARCHAR}
